namespace OpenTPW;

/// <summary>
/// The kart and water track slice's approximation register (docs/TRACKS.md). Each entry is tagged <c>[APPROX:TRACK-NNN]</c> at its code site (a retired one leaves its BIN labels, a reclassified one an <c>[EXT:name]</c> decision, docs/TRACKS.md); the
/// words before the colon name the topic. Everything else of the slice is traced from the Mac and Windows binaries (BIN labels at the code sites).
/// </summary>
public static class TrackApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("TRACK-001", "TRACK-HEIGHT: the vehicles sample the owner object of each probe in the original's modes (0x450EA0: surface records, terrain + the header's +0xA0, the instance mesh), a cell with no track or a station or add-on tile gives that object (0x452A60) and keeps the previous height without one, the face sampler bakes the node translations and its directed edge gate runs in host float, which equals the x87 sequence at control word 0x7F (0x4514CF, 24-bit); the tile instances stand on the midrange of the tile's 3 x 3 landscape vertices (0x466D70) with every mesh vertex draped onto the landscape (0x469A80); approximated: the instance mesh sampler (mode 4, +0x2C) reads every 0x8000 face of the model, where the original's 0x46A5A0 builds it through 0x469A80 from the node hierarchy with its own node filters, which are not traced (no track piece or station reaches it)"),
		("TRACK-002", "TRACK-HMP: the .hmp height profile is the original's per-object height map (loader 0x451640 from the mesh loader 0x4629D0, rebuilt from the mesh by 0x451880 when missing or mis-sized); the vehicles' sampler does not read it (0x4511A0 samples faces or the terrain sampler 0x4527F0, TRACK-001) and neither do OpenTPW's vehicles; the kit parses it; the readers of the object's map (+0xCC) are the cell-height lookup 0x452AE0 (the cell owner's map byte x 100/255 plus its base height, else the landscape; callers 0x45CDC0, 0x532FC0, 0x536CA0, 0x5370E0 and the tour code 0x55ABF0, 0x55C350, 0x55CC00, TOUR-005), the instance bounding box 0x466B70 (the map's +0x1C/+0x28 extremes plus the instance height; callers 0x556AF0, 0x556B90, 0x556DE0, 0x5587F0, 0x559060, 0x5597A0, 0x55A100), the ride preview 0x4689F0 (0x486410 from 0x4AB1B0) and the cell-flag copy of the mesh creation 0x463060 (bit 0x80 cells of the map written into the landscape cells; every shipped map's flags are zero), none of which belongs to the kart or water vehicles; what those readers decide in OpenTPW's tour, ghost and bounding-box code is not traced"),
		("TRACK-005", "TRACK-STATION: the station is the original's line of 0x52A1A0 from the attraction cell: two tiles of type 13 or 18 on the footprint's rows 1 and 2, the circuit starting at the first, the controller reference between the tiles (0x529E10, 0x545890) and the piece walks 0x52A490 and 0x52A700; the placement (0x524960 mode 4, 0x525254..0x525690) writes the station arms whatever the exit and entry type ops answer (0x5255D8..0x52572C), which the end state of the dual-arm placement matches; approximated: the exit and entry tiles (type 11 or 16, ops 0x87, 0x80, 0x82, 0x83) are laid with the first and the last line, the validation the placement runs on them, the priority demolition of op 0x87, the refused-entry case, the first line's start on an existing tile (0x52A1A0, 0x53AAC0, 0x539220) and what the placement charges for those two tiles are not reproduced"),
		("TRACK-010", "TRACK-BRIDGE: a kart or water tile with at most two arms and no corner (straights, single-arm ends, armless tiles, 0x538AA4..0x538B05) is a bridge when it replaced path cells; the original tests the map layer under the track (a path or queue under any of its four cells, kept there and re-tested when a path is laid later) and only type 25 tests map types 2, 7 and 30 (water, outside the park and the fixed walkway); OpenTPW's track replaces the paths, so it remembers them when the tile is laid, writes no type 25, and takes the ahead and behind neighbours of the second pass from the flow link (an end or armless tile without a link along it takes the positive axis), whose PC twin is not traced"),
		("TRACK-018", "TRACK-ANIM: the pieces' arm masks and their m clips play as the original triggers them (BUMP 17, the placement, line and edit walks), and the renderer draws texture-coordinate clips only, which is all the shipped pieces need; the track edit sub-modes 0xE and 0x13 are built (TrackEditor, TrackEditWriter: the pick test 0x539760, the cut 0x52B400 with the clear op 0x53B280, the end re-links 0x53BC60, the station repair 0x52FC80, the walk 0x526BD0 and the line tool from the open end 0x530830), Backspace and the demolition replay the corner stacks through the clears (0x52FE50, mode 0x35), the tool holds the PC's 1025 points (0x52FBF0) and the hover marks the pick and the cut path with the m_break and m_erase tile faces (0x10F of 0x52B400); residuals: the pick hover's glide, walls and neighbour raise and the blink of the ghost (BLUEPRINT-003), whether 0x52FC80 repairs the exit rather than the station's first tile, and the exit and entry validation difference"),
		("TRACK-026", "TRACK-HEADS: a kart's, boat's or bumper car's riders are drawn as head sprites at the head dummies (class 0x100000B1: numbers 1 and 2 in the karts, 1 to 5 in the wr_ring boats) through the ride-head renderer in the original's seat order (rider list order, 0x549C60, called by the vehicle creation 0x549DB0 for every family); 0x0044B410 is the PC twin of ADDHEAD (it marks the head record 0x14 bytes apart and has 0x00475A10 create the head thing, type 1 or 3 for a costume head; its callers are the seat code 0x549C60, 0x43B600, 0x548E80, 0x557D80 and 0x55D830), whose sprite the shared thing renderer draws (the sizes belong to the HEADS entries); the boarding guest between BUMP 1 and the car's creation is not traced"),
		("TRACK-032", "SAVED-RIDE CONTROLLER: a saved kart or water ride's controller is rebuilt after a fresh re-walk. Native loader 0x543560 instead reads chunk 3's 40-byte field payload (0xd0 is the in-memory ride stride), reconstructs a distinct 0x1c waypoint chain from ride and chunk 4 tile parameters, restores chunk 5's raw 0xac controller records with relocation keys, and chunk 6 selects the reference waypoint: first flag 4, then mandatory advance with wrap and flag 2 skipping. SaveTrackRideBlock only reads structural chunks; waypoint reconstruction, runtime restoration and saved-versus-fresh verdict semantics remain unimplemented"),
	};
}
